          children: order.items.map((item) {
            final isSelected = item.id == activeId;
            final isAccepted = item.acceptedRomoId != null ||
                item.status.toUpperCase() == 'CONFIRMED' ||
                item.status.toUpperCase() == 'DONE';
            final isMyItem = widget.isRomo &&
